INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(9031, 'plPL', 'Uciekajcie! Nadchodzą!', 'Uciekajcie! Nadchodzą!', 0),
(9591, 'plPL', 'Jeśli spadnę w otchłań, pociągnę was wszystkich, śmiertelnicy, za sobą!', '', 0),
(9592, 'plPL', '%s uciekają, gdy kontrolująca ich moc kuli słabnie.', '', 0),
(9793, 'plPL', '%s wzdryga się, a jego skóra zaczyna migotać.', '', 0),
(9958, 'plPL', 'Intruzi wdarli się do wylęgarni! Podnieść alarm! Chrońcie jaja za wszelką cenę!', '', 0),
(9961, 'plPL', 'Zapłacicie mi za to, że mnie do tego zmusiliście!', '', 0),
(9962, 'plPL', 'Głupcy! Te jaja są cenniejsze, niż sądzicie!', '', 0),
(9963, 'plPL', 'Nie... nie kolejne! Za to okrucieństwo zapłacicie głowami!', '', 0),
(9967, 'plPL', 'Nikt z waszego rodzaju nie powinien tu przebywać! Zgubiliście tylko samych siebie!', '', 0),
(9968, 'plPL', 'Sprytnie, śmiertelnicy, ale nie tak łatwo odciągnąć mnie od mojego sanktuarium!', '', 0);
